    # sorting (score, name) pairs orders by score first
    pass

challenge-set.solution:
def rank_by_score(pairs):
    swapped = []
    for name, score in pairs:
        swapped.append((score, name))
    swapped.sort()
    result = []
    for score, name in swapped:
        result.append((name, score))
    return result

challenge-set.starterCode:
def group_by_first_letter(words):
    groups = {}
    # a key that is not there yet needs an empty list before you can append
    return groups

challenge-set.solution:
def group_by_first_letter(words):
    groups = {}
    for word in words:
        letter = word[0]
        if letter not in groups:
            groups[letter] = []
        groups[letter].append(word)
    for letter in groups:
        groups[letter].sort()
    return groups

