level-project.solution:
PUNCTUATION = ".,!?;:"

def word_frequency(text):
    counts = {}
    for raw in text.split():
        word = raw.strip(PUNCTUATION).lower()
        if word == '':
            continue
        counts[word] = counts.get(word, 0) + 1
    return counts

