def merge_ledgers(a, b):
    totals = {}
    # count the totals, collect each ledger's names, then compare the two name sets
    return totals, []

exam.solution:
def merge_ledgers(a, b):
    totals = {}
    names_a = set()
    names_b = set()
    for name, amount in a:
        totals[name] = totals.get(name, 0) + amount
        names_a.add(name)
    for name, amount in b:
        totals[name] = totals.get(name, 0) + amount
        names_b.add(name)
    return totals, sorted(names_a & names_b)
